IGNORE = -100

def build_labels(input_ids, prompt_len, end_of_turn_id):
    labels = list(input_ids)
    for i in range(prompt_len):
        labels[i] = IGNORE
    for i, tok in enumerate(input_ids):
        if tok == end_of_turn_id:
            labels[i] = IGNORE   # special tokens aren't content
    return labels
